import React from 'react';
import { Composition } from 'remotion';
import content from '../content.json';
// Generated by `npm run assets` (scripts/build-assets.mjs).
import manifest from '../public/manifest.json';
import { Content, FaceShapes, FPS, H, Manifest, Props, timeline, W } from './FaceShapes';

const defaultProps: Props = { manifest: manifest as unknown as Manifest, content: content as unknown as Content };

export const Root: React.FC = () => (
  <Composition
    id="FaceShapes"
    component={FaceShapes}
    width={W}
    height={H}
    fps={FPS}
    durationInFrames={timeline(defaultProps.manifest, defaultProps.content).total}
    defaultProps={defaultProps}
    calculateMetadata={({ props }) => ({ durationInFrames: timeline((props as Props).manifest, (props as Props).content).total })}
  />
);
